import Dexie, { type Table, type EntityTable, type IndexableType } from 'dexie';
import { liveQuery } from 'dexie';

// ─── Type Re-exports ────────────────────────────────────────────────────────
export { Dexie, liveQuery };
export type { Table as DexieTable, EntityTable, IndexableType };

// ─── Typed DB Factory ───────────────────────────────────────────────────────

/**
 * Create a typed Dexie database instance with schema definitions.
 *
 * @example
 * ```ts
 * interface Friend {
 *   id: number;
 *   name: string;
 *   age: number;
 * }
 *
 * interface MyDB {
 *   friends: EntityTable<Friend, 'id'>;
 * }
 *
 * const db = createTypedDB<MyDB>('myDatabase', {
 *   friends: '++id, name, age',
 * });
 *
 * // Fully typed table access
 * await db.friends.add({ name: 'Alice', age: 30 });
 * ```
 *
 * @param name - The IndexedDB database name.
 * @param stores - Schema definition mapping table names to index declarations.
 * @param version - Schema version number (default: 1).
 */
export function createTypedDB<T extends Record<string, Table>>(
  name: string,
  stores: Record<keyof T, string>,
  version = 1
): Dexie & T {
  const db = new Dexie(name);
  db.version(version).stores(stores as Record<string, string>);
  return db as Dexie & T;
}

// ─── DB Export / Import / Clear ─────────────────────────────────────────────

/**
 * Export all data from a Dexie database as a plain object.
 *
 * @example
 * ```ts
 * const snapshot = await exportDB(db);
 * // { friends: [{ id: 1, name: 'Alice' }, ...], ... }
 * ```
 */
export async function exportDB(db: Dexie): Promise<Record<string, unknown[]>> {
  const result: Record<string, unknown[]> = {};
  for (const table of db.tables) {
    result[table.name] = await table.toArray();
  }
  return result;
}

/**
 * Import data into a Dexie database via `bulkPut` (upsert semantics).
 * Only tables present in `data` are affected; others remain untouched.
 *
 * @example
 * ```ts
 * await importDB(db, {
 *   friends: [{ id: 1, name: 'Alice', age: 30 }],
 * });
 * ```
 */
export async function importDB(db: Dexie, data: Record<string, unknown[]>): Promise<void> {
  const tableNames = Object.keys(data);
  const tables = tableNames
    .map((name) => db.tables.find((t) => t.name === name))
    .filter((t): t is Table => t != null);

  await db.transaction('rw', tables, async () => {
    for (const table of tables) {
      await table.bulkPut(data[table.name]!);
    }
  });
}

/**
 * Clear all data from every table in a Dexie database.
 *
 * @example
 * ```ts
 * await clearDB(db);
 * ```
 */
export async function clearDB(db: Dexie): Promise<void> {
  await db.transaction('rw', db.tables, async () => {
    for (const table of db.tables) {
      await table.clear();
    }
  });
}

import * as React from 'react';
import type { Collection, IndexableType, Table } from 'dexie';
import { useLiveQuery } from './use-live-query';

export interface UseDexiePaginationOptions<T, TKey extends IndexableType = IndexableType> {
  /** The Dexie table to paginate. */
  table: Table<T, TKey>;
  /** Optional transform applied to the collection before pagination (e.g. filter, orderBy). */
  query?: (collection: Collection<T, TKey>) => Collection<T, TKey>;
  /** Number of items per page. @default 10 */
  pageSize?: number;
  /** Zero-based initial page index. @default 0 */
  initialPage?: number;
  /** Dependency array — re-subscribes when values change. */
  deps?: unknown[];
}

export interface UseDexiePaginationReturn<T> {
  data: T[];
  page: number;
  pageSize: number;
  totalCount: number;
  totalPages: number;
  error: Error | null;
  setPage: (page: number) => void;
  setPageSize: (size: number) => void;
  hasNextPage: boolean;
  hasPreviousPage: boolean;
}

/**
 * Paginated, reactive queries over a Dexie table.
 *
 * Built on `useLiveQuery` — data updates automatically when underlying
 * IndexedDB records change.
 *
 * @example
 * ```tsx
 * const {
 *   data: friends,
 *   page,
 *   totalPages,
 *   setPage,
 *   isLoading,
 * } = useDexiePagination({
 *   table: db.friends,
 *   pageSize: 20,
 *   query: (col) => col.where('age').above(18),
 * });
 * ```
 */
export function useDexiePagination<T, TKey extends IndexableType = IndexableType>(
  options: UseDexiePaginationOptions<T, TKey>
): UseDexiePaginationReturn<T> {
  const { table, query, pageSize: initialPageSize = 10, initialPage = 0, deps = [] } = options;

  const [page, setPage] = React.useState(initialPage);
  const [pageSize, setPageSizeState] = React.useState(initialPageSize);

  // Reset to first page when pageSize or external deps change
  const setPageSize = React.useCallback((size: number) => {
    setPageSizeState(size);
    setPage(0);
  }, []);

  const queryRef = React.useRef(query);
  queryRef.current = query;

  const tableRef = React.useRef(table);
  tableRef.current = table;

  const { data: result, error } = useLiveQuery(
    async () => {
      const baseCollection = queryRef.current
        ? queryRef.current(tableRef.current.toCollection())
        : tableRef.current.toCollection();

      const [items, totalCount] = await Promise.all([
        baseCollection
          .offset(page * pageSize)
          .limit(pageSize)
          .toArray(),
        // Count needs its own collection instance (offset/limit mutate the collection)
        queryRef.current
          ? queryRef.current(tableRef.current.toCollection()).count()
          : tableRef.current.count(),
      ]);

      return { items, totalCount };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [page, pageSize, ...deps],
    { items: [] as T[], totalCount: 0 }
  );

  const totalCount = result?.totalCount ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
  const data = result?.items ?? [];

  return {
    data,
    page,
    pageSize,
    totalCount,
    totalPages,
    error,
    setPage,
    setPageSize,
    hasNextPage: page < totalPages - 1,
    hasPreviousPage: page > 0,
  };
}

import * as React from 'react';
import type { IndexableType, Table, UpdateSpec } from 'dexie';
import { useLiveQuery } from './use-live-query';

export interface UseDexieTableReturn<T, TKey extends IndexableType> {
  data: T[];
  error: Error | null;
  add: (item: T) => Promise<TKey>;
  put: (item: T) => Promise<TKey>;
  update: (key: TKey, changes: UpdateSpec<T>) => Promise<number>;
  remove: (key: TKey) => Promise<void>;
  bulkAdd: (items: T[]) => Promise<TKey>;
  bulkPut: (items: T[]) => Promise<TKey>;
  bulkDelete: (keys: TKey[]) => Promise<void>;
  clear: () => Promise<void>;
  getById: (key: TKey) => Promise<T | undefined>;
}

/**
 * Reactive CRUD hook for a Dexie table.
 *
 * Built on `useLiveQuery` — `data` updates automatically when underlying
 * IndexedDB records change.
 *
 * @example
 * ```tsx
 * const {
 *   data: friends,
 *   isLoading,
 *   error,
 *   add,
 *   remove,
 * } = useDexieTable(db.friends);
 *
 * // Mutations
 * await add({ name: 'Alice', age: 30 });
 * await remove(1);
 * ```
 */
export function useDexieTable<T, TKey extends IndexableType = IndexableType>(
  table: Table<T, TKey>,
  deps: unknown[] = []
): UseDexieTableReturn<T, TKey> {
  const tableRef = React.useRef(table);
  tableRef.current = table;

  // ── Reactive reads ────────────────────────────────────────────────────
  const { data, error } = useLiveQuery(
    () => tableRef.current.toArray(),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    deps,
    [] as T[]
  );

  // ── Mutations ─────────────────────────────────────────────────────────
  const add = (item: T) => tableRef.current.add(item) as Promise<TKey>;
  const put = (item: T) => tableRef.current.put(item) as Promise<TKey>;
  const update = (key: TKey, changes: UpdateSpec<T>) => tableRef.current.update(key, changes);
  const remove = (key: TKey) => tableRef.current.delete(key);
  const bulkAdd = (items: T[]) => tableRef.current.bulkAdd(items) as Promise<TKey>;
  const bulkPut = (items: T[]) => tableRef.current.bulkPut(items) as Promise<TKey>;
  const bulkDelete = (keys: TKey[]) => tableRef.current.bulkDelete(keys);
  const clear = () => tableRef.current.clear();
  const getById = (key: TKey) => tableRef.current.get(key);

  return {
    data: data ?? [],
    error,
    add,
    put,
    update,
    remove,
    bulkAdd,
    bulkPut,
    bulkDelete,
    clear,
    getById,
  };
}

import * as React from 'react';
import { useLiveQuery as useDexieLiveQuery } from 'dexie-react-hooks';

export interface UseLiveQueryResult<T> {
  data: T;
  error: Error | null;
}

/**
 * Wrapper around `dexie-react-hooks`' `useLiveQuery` that returns
 * `{ data, isLoading, error }` instead of throwing on error or
 * returning `undefined` while loading.
 *
 * @example
 * ```tsx
 * const { data: friends, isLoading, error } = useLiveQuery(
 *   () => db.friends.where('age').above(18).toArray(),
 *   [],
 *   [],
 * );
 * ```
 */
export function useLiveQuery<T>(
  querier: () => Promise<T> | T,
  deps?: unknown[]
): UseLiveQueryResult<T | undefined>;

export function useLiveQuery<T, TDefault>(
  querier: () => Promise<T> | T,
  deps: unknown[],
  defaultResult: TDefault
): UseLiveQueryResult<T | TDefault>;

export function useLiveQuery<T, TDefault>(
  querier: () => Promise<T> | T,
  deps?: unknown[],
  defaultResult?: TDefault
): UseLiveQueryResult<T | TDefault | undefined> {
  const [error, setError] = React.useState<Error | null>(null);

  const result = useDexieLiveQuery(
    async () => {
      try {
        setError(null);
        return await querier();
      } catch (e) {
        setError(e instanceof Error ? e : new Error(String(e)));
        return defaultResult;
      }
    },
    deps ?? [],
    defaultResult
  );

  const data = result ?? defaultResult;

  return { data, error };
}

export * from './dexie';
export * from './hooks/use-dexie-pagination';
export * from './hooks/use-dexie-table';
export * from './hooks/use-live-query';
